  ('st-ex-karamade-1', 'sent-ex-karamade-1', 'en', 'I walk from school to the sea.', 'authored'),
  ('st-ex-karamade-2', 'sent-ex-karamade-2', 'en', 'I study from morning until night.', 'authored'),
  ('st-ex-karamade-3', 'sent-ex-karamade-3', 'en', 'I work from Monday to Friday.', 'authored'),
  ('st-ex-karamade-4', 'sent-ex-karamade-4', 'en', 'I go from home to the office by train.', 'authored'),
  ('st-ex-yori-1', 'sent-ex-yori-1', 'en', 'I like meat more than fish.', 'authored'),
  ('st-ex-yori-2', 'sent-ex-yori-2', 'en', 'The train is faster than the car.', 'authored'),
  ('st-ex-yori-3', 'sent-ex-yori-3', 'en', 'I like the sea more than the mountains.', 'authored'),
  ('st-ex-yori-4', 'sent-ex-yori-4', 'en', 'Films are more interesting than books.', 'authored'),
  ('st-ex-masenka-1', 'sent-ex-masenka-1', 'en', 'Won''t you come along?', 'authored'),
  ('st-ex-masenka-2', 'sent-ex-masenka-2', 'en', 'Shall we watch a film?', 'authored'),
  ('st-ex-masenka-3', 'sent-ex-masenka-3', 'en', 'Would you like some tea?', 'authored'),
  ('st-ex-masenka-4', 'sent-ex-masenka-4', 'en', 'Shall we swim in the sea?', 'authored'),
